    grid = [[0] * N for _ in range(N)]
    visited = [[False] * N for _ in range(N)]

    # Initialize grid with given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value
        visited[x-1][y-1] = True

    # Helper function to get neighbors
    def get_neighbors(x, y):
        neighbors = []
        if x > 0:
            neighbors.append((x-1, y))
        if y > 0:
            neighbors.append((x, y-1))
        if x < N-1:
            neighbors.append((x+1, y))
        if y < N-1:
            neighbors.append((x, y+1))
        return neighbors

    # Function to calculate the maximum sum
    def max_sum(x, y, visited, path_sum):
        if (x, y) == (N-1, N-1):
            return path_sum
        max_value = 0
        for neighbor in get_neighbors(x, y):
            nx, ny = neighbor
            if not visited[nx][ny]:
                visited[nx][ny] = True
                max_value = max(max_value, max_sum(nx, ny, visited, path_sum + grid[nx][ny]))
                visited[nx][ny] = False
        return max_value

    visited[0][0] = True
    max_sum_value = max_sum(0, 0, visited, grid[0][0])
    visited[0][0] = False

    return max_sum_value

