def cantor_numbering(N: int) -> str:
    if N <= 0:
        raise ValueError("N must be a positive integer")

    level = 1
    while (level * (level + 1)) // 2 < N:
        level += 1

    remaining = N - ((level - 1) * level) // 2

    if level % 2 == 0:
        numerator = remaining
        denominator = level + 1 - remaining
    else:
        numerator = level + 1 - remaining
        denominator = remaining

    return f"{numerator}/{denominator}"

