def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    if not (1 <= M <= 100 and 1 <= N <= 100 and 0 <= K <= M and 0 <= L <= N and 0 <= D <= M * N):
        raise ValueError("Invalid input for M, N, K, L, or D")

    if not all(1 <= xi, yi, pi, qi <= N for xi, yi, pi, qi in chatting_pairs):
        raise ValueError("Invalid student positions in chatting_pairs")

    row_separations = [0] * (M + 1)
    col_separations = [0] * (N + 1)

    for xi, yi, pi, qi in chatting_pairs:
        if yi == qi:
            if xi < pi:
                row_separations[xi] += 1
            else:
                row_separations[pi] += 1
        elif xi == pi:
            if yi < qi:
                col_separations[yi] += 1
            else:
                col_separations[qi] += 1

    best_rows = sorted(range(1, M + 1), key=lambda r: -row_separations[r])[:K]
    best_cols = sorted(range(1, N + 1), key=lambda c: -col_separations[c])[:L]

    return ' '.join(map(str, best_rows)), ' '.join(map(str, best_cols))

