def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("Invalid input values")
    if n == 1 and m == 0:
        return 1
    dp = [[0] * (m + 1) for _ in range(n)]
    for i in range(n):
