    for passes in range(1, m + 1):
        dp[0][passes] = dp[n-1][passes-1]
        dp[n-1][passes] = dp[0][passes-1]
        for i in range(1, n-1):
            dp[i][passes] = dp[i-1][passes-1] + dp[i+1][passes-1]
    return dp[0][m]

