        return "Failed"

    cipher_map = {}
    for e, o in zip(encoded, original):
        if e in cipher_map:
            if cipher_map[e] != o:
                return "Failed"
        else:
            cipher_map[e] = o

    if len(cipher_map) != len(set(cipher_map.values())):
        return "Failed"

    decoded_message = []
